<?php if(!$rows):?><section class="admin-panel monitor-empty-panel"><div class="monitor-empty"><?=ui_icon('check')?> <div><strong>No incidents match this view.</strong><p>The monitor will populate automatically when a health check or runtime request fails.</p></div></div></section><?php else:?><div class="incident-cards"><?php foreach($rows as $row):?><article class="incident-card status-<?=e((string)$row['status'])?> severity-border-<?=e((string)$row['severity'])?>"><div class="incident-card-head"><div><span class="incident-severity severity-<?=e((string)$row['severity'])?>"><?=e(strtoupper((string)$row['severity']))?></span><span class="incident-state <?=e((string)$row['status'])?>"><?=e(strtoupper((string)$row['status']))?></span><?php if(!empty($row['critical_retained'])):?><span class="incident-retained">RETAINED</span><?php endif;?></div><strong>×<?=e((string)$row['count'])?></strong></div><h2><?=e((string)$row['title'])?></h2><p><?=e((string)$row['message'])?></p><dl><div><dt>Source</dt><dd><?=e((string)$row['source'])?> / <?=e((string)$row['category'])?></dd></div><div><dt>Route</dt><dd><?=e((string)($row['method']??''))?> <?=e((string)($row['route']??'—'))?></dd></div><div><dt>First seen</dt><dd><?=e((string)$row['first_seen_at'])?></dd></div><div><dt>Last seen</dt><dd><?=e((string)$row['last_seen_at'])?></dd></div><?php if(!empty($row['file'])):?><div><dt>Location</dt><dd><?=e((string)$row['file'])?><?=!empty($row['line'])?':'.e((string)$row['line']):''?></dd></div><?php endif;?><?php if(($row['status']??'')==='resolved'):?><div><dt>Resolved</dt><dd><?=e((string)($row['resolved_at']??'—'))?></dd></div><div class="span-2"><dt>Resolution</dt><dd><?=e((string)($row['resolution']??'Recovered automatically'))?></dd></div><?php endif;?></dl></article><?php endforeach;?></div><?php endif;?>
